INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('1119', '47', '11893', '174', ' invitacion_licitacion ', ' invitacion_licitacion ', ' mensaje_whatsapp ', ' whatsapp ', ' Saludo recibido; se confirmó envío de invitación a licitación y se compartieron recursos para registrarse y consultar resultados. ', ' interaccion_informativa ', '{"email": "maduenogabriela8@gmail.com", "tipo_plan": "evaluacion", "observaciones": "Cliente en etapa ''invitacion_licitacion''. Se informó tutorial y link de resultados; no se ofrecieron gestiones.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', ' neutral ', '2026-07-07T16:09:41.351481+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('1120', '47', '11893', '174', ' invitacion_licitacion ', ' invitacion_licitacion ', ' mensaje_whatsapp ', ' whatsapp ', ' El ahorrista preguntó sobre montos para licitar; se derivó a equipo humano y se compartieron enlaces oficiales. ', ' interaccion_informativa ', '{"email": "maduenogabriela8@gmail.com", "tipo_plan": "evaluacion", "observaciones": "Consulta sobre con cuánto licitar derivada al equipo de Plan Óvalo; se proveyeron enlaces y contacto WhatsApp.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', ' interesado ', '2026-07-07T16:09:46.350933+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('1121', '1530', '11945', '128', NULL, 'invitacion_licitacion', 'email_wpp_invita_licitacion', 'email_wpp', 'Invitación a licitación enviada por email y WhatsApp', 'invitacion_licitacion_enviada', '{"modelo": "RANGER XL 80/20", "plan_rate": 80, "fue_insert": true, "nro_solicitud": "1397985"}', NULL, '2026-07-07T16:09:56.789759+00:00');
