INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3125', '85', '11623', '102', 'contactado_sin_respuesta', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Ahorrista indicó haber pagado. Info_status muestra deuda (OVERDUE) por $1.315.126,63. Se solicitó fecha/importe/medio/nro operación para verificar.', 'escalacion', '{"email": "PABLO.ZELARAYAN@CRZELARAYAN.COM", "tipo_plan": "evaluacion", "observaciones": "Ahorrista informó haber realizado el pago. Sistema presenta status OVERDUE con monto a regularizar. Solicitar datos de pago para verificación con Administración.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'colaborativo', '2026-08-24T20:35:24.409991+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3126', '1186', '11736', '116', 'escalado_humano', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Cliente informó que realizó el pago. Caso en escalado_humano; se solicitará y/o verificará comprobante y se aguardará acreditación por equipo administrativo.', 'escalacion', '{"email": "ISAAC_S_PRENGER@HOTMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "Ahorrista informó haber realizado el pago. Caso derivado a equipo administrativo para verificación de acreditación. Pendiente confirmación en 24-48 hs hábiles.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'colaborativo', '2026-08-24T20:36:58.612153+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3127', '1186', '11736', '116', 'escalado_humano', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Ahorrista reporta haber pagado y reclamó en dos ocasiones; perfil ya se encuentra en etapa escalado_humano y espera verificación de acreditación por el equipo administrativo.', 'escalacion', '{"email": "ISAAC_S_PRENGER@HOTMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "Cliente informa haber pagado y reclama acreditación. Caso ya elevado a administrador; pendiente verificación de acreditación. Notas previas incluyen referencia de operación y conciliación en curso.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'evasivo', '2026-08-24T20:37:03.215444+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3128', '1186', '11736', '116', 'escalado_humano', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Cliente confirma haber pagado el cupón. Caso en revisión administrativa; pedido de comprobante para agilizar acreditación.', 'escalacion', '{"email": "ISAAC_S_PRENGER@HOTMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "Ahorrista confirma haber abonado el monto del cupón. Caso derivado al equipo administrativo para verificación de acreditación. Solicitar comprobante/numero de operacion para agilizar.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'evasivo', '2026-08-24T20:37:34.107628+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3129', '1186', '11736', '116', 'escalado_humano', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Cliente consultó cómo enviar comprobante; se indicó procedimiento para adjuntar foto/PDF o enviar número de operación, y se ofreció derivación a canales administrativos.', 'escalacion', '{"email": "ISAAC_S_PRENGER@HOTMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "Se indicó al cliente cómo enviar comprobante por este chat (foto/PDF) o alternativa de enviar número de operación; se ofreció derivación a los WhatsApp administrativos.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'evasivo', '2026-08-24T20:39:16.572187+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3130', '1186', '11736', '116', 'escalado_humano', 'escalado_humano', 'mensaje_whatsapp', 'whatsapp', 'Cliente envió número de operación 117361160000; se derivó a administración para verificación de acreditación.', 'escalacion', '{"email": "ISAAC_S_PRENGER@HOTMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "Ahorrista proporcionó número de operación 117361160000. Dato registrado y derivado al equipo administrativo para verificación de acreditación. Pendiente confirmación en 24-48 hs hábiles.", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'colaborativo', '2026-08-24T20:40:10.265827+00:00');
INSERT INTO "ovalo-cobranzas".cobranza_etapas_historial VALUES ('3131', '49', '11896', '11', 'contactado_sin_respuesta', 'conversacion_iniciada', 'mensaje_whatsapp', 'whatsapp', 'Cliente indicó haber realizado el pago. Se solicitó fecha, medio y comprobante para verificar.', 'informacion_recabada', '{"email": "JAVIER34285@GMAIL.COM", "tipo_plan": "evaluacion", "observaciones": "El ahorrista declara haber pagado; se solicitó fecha/medio/comprobante para verificación con Administración", "fecha_compromiso": null, "cuotas_comprometidas": 0}', 'colaborativo', '2026-08-24T20:55:57.905795+00:00');
